window.STARTGuests={updateCount,get count(){return openBillCount;},choose,show,cash,api,selectCafe,updateCafeContext,clearCafe(){cafeBill=null;const f=document.querySelector("#checkout");if(window.STARTCafeGuest&&!window.STARTCafeGuest.set(null))return false;if(f)delete f.dataset.guestBill;const url=new URL(location.href);url.searchParams.delete('guestBill');history.replaceState(null,'',url);updateCafeContext();dispatchEvent(new Event('resize'));return true;}};new MutationObserver(mount).observe(document.body,{childList:true,subtree:true});mount();try{if(parent!==window&&parent.STARTGuests?.count!==null)updateCount(parent.STARTGuests?.count);}catch{}
